arguments.cmd:
cd /app && cat > output/assets/styles.css <<'EOF'
:root{
  --bg0:#0D1B2A;
  --bg1:#0F2438;
  --surface:#122C44;
  --surface2:#162F48;
  --stroke:rgba(255,255,255,.10);
  --stroke2:rgba(255,255,255,.16);
  --text:#EAF2FF;
  --muted:rgba(234,242,255,.72);
  --muted2:rgba(234,242,255,.58);
  --accent:#00B4D8;
  --accent2:#0077B6;
  --ok:#6CC24A;
  --warn:#FFCC66;
  --danger:#FF6B6B;
  --shadow:0 18px 60px rgba(0,0,0,.45);
  --shadow2:0 10px 30px rgba(0,0,0,.35);
  --radius-lg:20px;
  --radius-md:14px;
  --radius-sm:12px;
  --container:1160px;
  --ring:0 0 0 3px rgba(0,180,216,.35);
  --ring2:0 0 0 3px rgba(108,194,74,.30);
  --ease:cubic-bezier(.2,.8,.2,1);
  --dur:220ms;
}

*{box-sizing:border-box}
html{color-scheme:dark}
html,body{height:100%}
body{
  margin:0;
  font-family:Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background:radial-gradient(1200px 700px at 20% -10%, rgba(0,180,216,.18), transparent 55%),
             radial-gradient(900px 500px at 90% 0%, rgba(0,119,182,.16), transparent 52%),
             linear-gradient(180deg, var(--bg0), #07131F 70%, #06101A);
  color:var(--text);
  line-height:1.55;
}

img{max-width:100%; height:auto}

a{color:inherit; text-decoration:none}
a:hover{text-decoration:none}

.container{max-width:var(--container); margin:0 auto; padding:0 20px}

.skip-link{
  position:absolute; left:-999px; top:8px;
  background:var(--surface);
  border:1px solid var(--stroke2);
  padding:10px 12px; border-radius:10px; z-index:2000;
}
.skip-link:focus{left:12px; box-shadow:var(--ring)}

/* Header */
.site-header{position:sticky; top:0; z-index:1000; backdrop-filter:saturate(140%) blur(10px);
  background:rgba(7,19,31,.58); border-bottom:1px solid rgba(255,255,255,.06);
}
.navbar{display:flex; align-items:center; justify-content:space-between; gap:18px; padding:14px 0}
.brand{display:flex; align-items:center; gap:12px; min-width:200px}
.logo{
  width:34px; height:34px; border-radius:12px;
  background:conic-gradient(from 210deg, rgba(0,180,216,.95), rgba(0,119,182,.85), rgba(108,194,74,.7), rgba(0,180,216,.95));
  box-shadow:0 10px 30px rgba(0,180,216,.12);
}
.brand-name{font-weight:650; letter-spacing:.2px}
.brand-sub{display:block; font-size:12px; color:var(--muted2); margin-top:-2px}

.nav-links{display:flex; align-items:center; gap:8px; flex-wrap:wrap}
.nav-item{position:relative}
.nav-link{
  display:inline-flex; align-items:center; gap:8px;
  padding:10px 12px; border-radius:12px;
  color:var(--muted);
  border:1px solid transparent;
  transition:background var(--dur) var(--ease), border var(--dur) var(--ease), color var(--dur) var(--ease);
}
.nav-link:hover{background:rgba(255,255,255,.05); border-color:rgba(255,255,255,.08); color:var(--text)}
.nav-link[aria-current="page"]{background:rgba(0,180,216,.10); border-color:rgba(0,180,216,.22); color:var(--text)}

.dropdown-toggle::after{content:""; width:10px; height:10px; display:inline-block; transform:translateY(1px) rotate(45deg);
  border-right:2px solid rgba(234,242,255,.70); border-bottom:2px solid rgba(234,242,255,.70); margin-left:2px;
}
.dropdown{
  position:absolute; left:0; top:46px; min-width:260px;
  padding:10px; border-radius:16px;
  background:rgba(18,44,68,.92);
  border:1px solid rgba(255,255,255,.10);
  box-shadow:var(--shadow2);
  transform-origin:top left;
  transform:translateY(-6px) scale(.98);
  opacity:0; pointer-events:none;
  transition:opacity 160ms var(--ease), transform 160ms var(--ease);
}
.nav-item:focus-within .dropdown, .nav-item:hover .dropdown{opacity:1; pointer-events:auto; transform:translateY(0) scale(1)}
.dropdown a{
  display:flex; align-items:flex-start; gap:12px;
  padding:12px; border-radius:14px;
  border:1px solid transparent;
  transition:background var(--dur) var(--ease), border var(--dur) var(--ease);
}
.dropdown a:hover{background:rgba(255,255,255,.05); border-color:rgba(255,255,255,.08)}
.dd-title{font-weight:600}
.dd-desc{font-size:12px; color:var(--muted2); margin-top:2px}
.dd-ic{width:34px; height:34px; border-radius:12px; display:grid; place-items:center; flex:none;
  background:linear-gradient(180deg, rgba(0,180,216,.18), rgba(0,119,182,.10));
  border:1px solid rgba(0,180,216,.20);
}

.nav-actions{display:flex; align-items:center; gap:10px; justify-content:flex-end; min-width:220px}
.btn{
  display:inline-flex; align-items:center; justify-content:center; gap:10px;
  padding:12px 14px; border-radius:14px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.05);
  color:var(--text);
  font-weight:600; letter-spacing:.2px;
  transition:transform 140ms var(--ease), background var(--dur) var(--ease), border var(--dur) var(--ease), box-shadow var(--dur) var(--ease);
  cursor:pointer;
  text-decoration:none;
}
.btn:hover{background:rgba(255,255,255,.08); border-color:rgba(255,255,255,.18)}
.btn:active{transform:translateY(1px) scale(.99)}
.btn:focus-visible{outline:none; box-shadow:var(--ring)}

.btn-primary{
  border-color:rgba(0,180,216,.36);
  background:linear-gradient(180deg, rgba(0,180,216,.95), rgba(0,119,182,.92));
  box-shadow:0 16px 40px rgba(0,180,216,.18);
}
.btn-primary:hover{filter:saturate(1.05) brightness(1.02)}

.btn-ghost{background:transparent}
.btn-ghost:hover{background:rgba(255,255,255,.06)}

.icon{width:16px; height:16px; display:inline-block}

.mobile-toggle{
  display:none;
  width:44px; height:44px;
  border-radius:14px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.05);
}
.mobile-toggle:focus-visible{outline:none; box-shadow:var(--ring)}

/* Layout blocks */
.section{padding:70px 0}
.section-tight{padding:48px 0}
.section-title{font-size:34px; line-height:1.12; letter-spacing:-.02em; margin:0 0 10px}
.section-kicker{color:var(--muted2); font-weight:650; letter-spacing:.12em; text-transform:uppercase; font-size:12px}
.section-sub{color:var(--muted); max-width:70ch; margin:0}

.card{
  background:linear-gradient(180deg, rgba(18,44,68,.88), rgba(12,28,44,.88));
  border:1px solid rgba(255,255,255,.10);
  border-radius:var(--radius-lg);
  box-shadow:var(--shadow2);
}

.grid{display:grid; gap:18px}

.hero{
  padding:68px 0 34px;
}
.hero-wrap{display:grid; grid-template-columns:1.15fr .85fr; gap:26px; align-items:center}
.hero h1{font-size:46px; line-height:1.06; margin:0 0 14px; letter-spacing:-.03em}
.hero p{margin:0 0 18px; color:var(--muted); font-size:17px; max-width:64ch}
.hero-actions{display:flex; gap:12px; flex-wrap:wrap; margin-top:10px}
.hero-badges{display:flex; gap:10px; flex-wrap:wrap; margin-top:18px}
.badge{display:inline-flex; align-items:center; gap:8px; padding:8px 10px; border-radius:999px;
  background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.10);
  color:var(--muted); font-weight:600; font-size:13px;
}
.badge .dot{width:8px; height:8px; border-radius:999px; background:var(--accent)}

.hero-panel{padding:18px}
.hero-panel .panel-title{font-weight:650; margin:0 0 8px}
.hero-panel .panel-sub{color:var(--muted2); font-size:13px; margin:0 0 12px}
.hero-panel .panel-grid{display:grid; grid-template-columns:1fr 1fr; gap:12px}
.kpi{padding:12px; border-radius:16px; border:1px solid rgba(255,255,255,.10); background:rgba(255,255,255,.04)}
.kpi .k{font-size:12px; color:var(--muted2)}
.kpi .v{font-size:18px; font-weight:700; margin-top:6px}

/* Tabs */
.tabs{display:flex; gap:8px; flex-wrap:wrap}
.tab{
  padding:10px 12px; border-radius:999px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.04);
  color:var(--muted);
  cursor:pointer;
  transition:background var(--dur) var(--ease), border var(--dur) var(--ease), color var(--dur) var(--ease), transform 140ms var(--ease);
}
.tab:hover{background:rgba(255,255,255,.07); color:var(--text)}
.tab[aria-selected="true"]{background:rgba(0,180,216,.12); border-color:rgba(0,180,216,.28); color:var(--text)}
.tab:active{transform:translateY(1px)}
.tab:focus-visible{outline:none; box-shadow:var(--ring)}

.tabpanels{margin-top:14px}
.panel{
  padding:18px;
  border-radius:var(--radius-lg);
  border:1px solid rgba(255,255,255,.10);
  background:rgba(255,255,255,.03);
}
.panel[hidden]{display:none}
.crossfade{position:relative}
.crossfade > .panel{animation:fadeIn 220ms var(--ease)}
@keyframes fadeIn{from{opacity:0; transform:translateY(4px)} to{opacity:1; transform:translateY(0)}}
@media (prefers-reduced-motion: reduce){
  .crossfade > .panel{animation:none}
  .btn,.tab,.nav-link{transition:none}
}

/* Use case cards */
.use-case-grid{grid-template-columns:repeat(3, minmax(0,1fr))}
.uc-card{padding:18px; border-radius:var(--radius-lg); border:1px solid rgba(255,255,255,.10);
  background:linear-gradient(180deg, rgba(18,44,68,.78), rgba(12,28,44,.72));
  transition:transform 160ms var(--ease), border 160ms var(--ease), background 160ms var(--ease);
}
.uc-card:hover{transform:translateY(-2px); border-color:rgba(0,180,216,.24); background:linear-gradient(180deg, rgba(18,44,68,.88), rgba(12,28,44,.80));}
.uc-card:focus-visible{outline:none; box-shadow:var(--ring)}
.uc-title{font-weight:700; margin:0 0 8px}
.uc-desc{margin:0; color:var(--muted)}
.uc-meta{margin-top:12px; display:flex; align-items:center; gap:10px; color:var(--muted2); font-size:13px}

/* Feature banner */
.banner{
  display:flex; gap:16px; align-items:center; justify-content:space-between;
  padding:18px; border-radius:var(--radius-lg);
  background:linear-gradient(180deg, rgba(0,180,216,.14), rgba(0,119,182,.08));
  border:1px solid rgba(0,180,216,.24);
}
.banner .b-title{font-weight:750}
.banner .b-sub{color:var(--muted); margin-top:2px}

/* Diagrams */
.diagram{padding:18px}
.diagram svg{width:100%; height:auto}
.diagram-title{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:10px}
.diagram-title h3{margin:0; font-size:18px}
.diagram-title p{margin:0; color:var(--muted2); font-size:13px}

/* Platform benefits */
.benefits{grid-template-columns:repeat(5, minmax(0,1fr))}
.benefit{padding:16px; border-radius:18px; border:1px solid rgba(255,255,255,.10); background:rgba(255,255,255,.03)}
.benefit h4{margin:0 0 6px; font-size:14px}
.benefit p{margin:0; color:var(--muted); font-size:13px}

/* Stats circles */
.stats{grid-template-columns:repeat(3, minmax(0,1fr))}
.stat{padding:18px; display:flex; gap:14px; align-items:center}
.ring{
  width:86px; height:86px; border-radius:999px;
  background:conic-gradient(from -90deg, rgba(0,180,216,.95) var(--pct), rgba(255,255,255,.10) 0);
  display:grid; place-items:center;
  border:1px solid rgba(255,255,255,.10);
}
.ring .inner{
  width:66px; height:66px; border-radius:999px;
  background:linear-gradient(180deg, rgba(18,44,68,.95), rgba(12,28,44,.92));
  border:1px solid rgba(255,255,255,.10);
  display:grid; place-items:center;
  font-weight:800;
}
.stat .label{color:var(--muted); font-size:13px}
.stat .value{font-weight:800; font-size:18px; margin-bottom:4px}

/* Timeline */
.timeline{display:grid; gap:14px}
.t-item{padding:16px; border-radius:18px; border:1px solid rgba(255,255,255,.10); background:rgba(255,255,255,.03)}
.t-head{display:flex; align-items:baseline; justify-content:space-between; gap:10px}
.t-duration{font-weight:850; letter-spacing:.02em}
.t-desc{color:var(--muted); margin-top:6px}
.progress{height:10px; border-radius:999px; background:rgba(255,255,255,.08); border:1px solid rgba(255,255,255,.10); overflow:hidden; margin-top:12px}
.bar{height:100%; width:var(--w); background:linear-gradient(90deg, rgba(0,180,216,.95), rgba(0,119,182,.95)); border-radius:999px}

/* Accordion */
.accordion{display:grid; gap:12px}
.acc-item{border-radius:18px; border:1px solid rgba(255,255,255,.10); background:rgba(255,255,255,.03); overflow:hidden}
.acc-btn{width:100%; text-align:left; padding:16px; background:transparent; border:0; color:var(--text);
  display:flex; align-items:center; justify-content:space-between; gap:12px; font:inherit; cursor:pointer}
.acc-title{font-weight:750}
.acc-ic{width:34px; height:34px; border-radius:12px; display:grid; place-items:center;
  background:rgba(0,180,216,.12); border:1px solid rgba(0,180,216,.22)}
.acc-panel{padding:0 16px 16px; color:var(--muted); display:none}
.acc-item[data-open="true"] .acc-panel{display:block; animation:fadeIn 220ms var(--ease)}
.acc-item[data-open="true"] .acc-btn{background:rgba(255,255,255,.03)}

/* Carousel */
.carousel{position:relative; overflow:hidden}
.carousel-track{display:flex; transition:transform 320ms var(--ease); will-change:transform}
.t-card{min-width:100%; padding:22px; border-radius:var(--radius-lg); border:1px solid rgba(255,255,255,.10);
  background:linear-gradient(180deg, rgba(18,44,68,.78), rgba(12,28,44,.70))}
.quote{font-size:18px; line-height:1.35; margin:0 0 12px}
.attrib{color:var(--muted2); font-size:13px; margin:0}
.dots{display:flex; justify-content:center; gap:10px; margin-top:14px}
.dot-btn{width:12px; height:12px; border-radius:999px; border:1px solid rgba(255,255,255,.16); background:rgba(255,255,255,.06); cursor:pointer}
.dot-btn[aria-selected="true"]{background:rgba(0,180,216,.85); border-color:rgba(0,180,216,.35)}
.dot-btn:focus-visible{outline:none; box-shadow:var(--ring)}

/* Forms */
.form-card{padding:22px}
.form-grid{display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:14px}
.field{display:grid; gap:6px}
.label{font-size:13px; color:var(--muted); font-weight:650}
.input, select, textarea{
  width:100%;
  border-radius:14px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.04);
  padding:12px 12px;
  color:var(--text);
  font:inherit;
  outline:none;
  transition:border var(--dur) var(--ease), box-shadow var(--dur) var(--ease), background var(--dur) var(--ease);
}
.input:focus, select:focus, textarea:focus{box-shadow:var(--ring); border-color:rgba(0,180,216,.30); background:rgba(255,255,255,.06)}
textarea{min-height:110px; resize:vertical}
.help{font-size:12px; color:var(--muted2)}
.error{font-size:12px; color:rgba(255,107,107,.95); display:none}
.field[data-error="true"] .error{display:block}
.field[data-error="true"] .input, .field[data-error="true"] select, .field[data-error="true"] textarea{border-color:rgba(255,107,107,.55); box-shadow:0 0 0 3px rgba(255,107,107,.18)}
.form-actions{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-top:16px; flex-wrap:wrap}
.notice{color:var(--muted2); font-size:12px}

/* Footer */
.site-footer{border-top:1px solid rgba(255,255,255,.06); background:rgba(7,19,31,.55)}
.footer-grid{display:grid; grid-template-columns:2fr 1fr 1fr 1fr; gap:18px; padding:34px 0}
.footer-title{font-weight:750}
.footer-sub{color:var(--muted); max-width:50ch}
.footer-col a{display:block; padding:8px 0; color:var(--muted);}
.footer-col a:hover{color:var(--text)}
.footer-kicker{color:var(--muted2); font-size:12px; font-weight:750; letter-spacing:.12em; text-transform:uppercase}
.footer-bottom{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:14px 0; color:var(--muted2); font-size:12px; border-top:1px solid rgba(255,255,255,.06)}

/* Cookie banner */
.cookie{
  position:fixed; left:18px; right:18px; bottom:18px; z-index:1200;
  max-width:920px; margin:0 auto;
  padding:14px;
  border-radius:18px;
  background:rgba(18,44,68,.92);
  border:1px solid rgba(255,255,255,.12);
  box-shadow:var(--shadow);
  display:none;
}
.cookie[data-show="true"]{display:block; animation:fadeIn 220ms var(--ease)}
.cookie .row{display:flex; align-items:flex-start; justify-content:space-between; gap:12px}
.cookie p{margin:0; color:var(--muted); font-size:13px}
.cookie .cookie-actions{display:flex; gap:10px; flex-wrap:wrap}

/* Responsive */
@media (max-width: 980px){
  .hero-wrap{grid-template-columns:1fr;}
  .benefits{grid-template-columns:repeat(2, minmax(0,1fr))}
  .use-case-grid{grid-template-columns:repeat(2, minmax(0,1fr))}
  .footer-grid{grid-template-columns:1.3fr 1fr 1fr;}
}
@media (max-width: 720px){
  .nav-links{display:none}
  .mobile-toggle{display:inline-grid; place-items:center}
  .nav-actions{min-width:auto}
  .hero h1{font-size:38px}
  .stats{grid-template-columns:1fr}
  .form-grid{grid-template-columns:1fr}
  .benefits{grid-template-columns:1fr}
  .use-case-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
}

/* Mobile menu */
.mobile-menu{
  display:none;
  border-top:1px solid rgba(255,255,255,.06);
  background:rgba(7,19,31,.72);
}
.mobile-menu[data-open="true"]{display:block}
.mobile-menu a{display:block; padding:12px 0; color:var(--muted)}
.mobile-menu a:hover{color:var(--text)}
.mobile-menu .mm-group{padding:12px 0; border-bottom:1px solid rgba(255,255,255,.06)}
.mobile-menu .mm-title{color:var(--muted2); font-size:12px; font-weight:750; letter-spacing:.12em; text-transform:uppercase; margin-bottom:8px}
EOF

