const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const pages = ['index.html','platform-overview.html','security.html','integration.html','request-demo.html'];
  for(const p of pages){
    await page.goto('http://127.0.0.1:4173/'+p, { waitUntil: 'networkidle' });
    const title = await page.title();
    const h1 = await page.locator('h1').first().innerText();
    console.log(p, '->', title, '| h1:', h1.slice(0,60));
  }
  // Smoke: cookie banner
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.removeItem('wellstream_cookie_pref'));
  await page.reload({ waitUntil: 'networkidle' });
  const cookieVisible = await page.locator('[data-cookie][data-show="true"]').count();
  console.log('cookieVisible', cookieVisible);
  if(cookieVisible){
    await page.locator('[data-cookie-accept]').click();
    const stored = await page.evaluate(() => localStorage.getItem('wellstream_cookie_pref'));
    console.log('cookieStored', stored);
  }

  // Smoke: tabs on integration
  await page.goto('http://127.0.0.1:4173/integration.html', { waitUntil: 'networkidle' });
  await page.locator('#int-api-btn').click();
  const apiHidden = await page.locator('#int-api[hidden]').count();
  const etlHidden = await page.locator('#int-etl[hidden]').count();
  console.log('tabs switch ok:', apiHidden===0 && etlHidden===1);

  // Smoke: form validation
  await page.goto('http://127.0.0.1:4173/request-demo.html', { waitUntil: 'networkidle' });
  await page.locator('button[type=submit]').click();
  const errors = await page.locator('[data-field][data-error="true"]').count();
  console.log('form errors:', errors);

  await browser.close();
})().catch(e=>{console.error(e); process.exit(1);});
